class Parser:
    def __init__(self, expression):
        self.tokens = self.tokenize(expression)
        self.current_token_index = 0

    def tokenize(self, expression):
        tokens = []
        num_buffer = []
        for char in expression:
            if char in '0123456789.':
                num_buffer.append(char)
            else:
                if num_buffer:
                    tokens.append(''.join(num_buffer))
                    num_buffer = []
                if char in '+-*/()':
                    tokens.append(char)
        if num_buffer:
            tokens.append(''.join(num_buffer))
        return tokens

    def parse(self):
        return self.expr()

    def expr(self):
        result = self.term()
        while self.current_token() in ('+', '-'):
            op = self.current_token()
            self.advance()
            right_term = self.term()
            if op == '+':
                result += right_term
            elif op == '-':
                result -= right_term
        return result

    def term(self):
        result = self.factor()
        while self.current_token() in ('*', '/'):
            op = self.current_token()
            self.advance()
            right_factor = self.factor()
            if op == '*':
                result *= right_factor
            elif op == '/':
                result /= right_factor
        return result

    def factor(self):
        if self.current_token() == '(':
            self.advance()
            result = self.expr()
            self.advance()  # Skip closing ')'
            return result
        else:
            num = float(self.current_token())
            self.advance()
            return num

    def current_token(self):
        if self.current_token_index < len(self.tokens):
            return self.tokens[self.current_token_index]
        return None

    def advance(self):
        self.current_token_index += 1

