def evaluate(expr: str) -> float:
    """
    Evaluates a mathematical expression using the Shunting Yard algorithm 
    for parsing and a stack based method for evaluation. Supports +, -, *, /, 
    parentheses, and floating-point numbers.
    """

    def precedence(op: str) -> int:
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_op(a: float, b: float, op: str) -> float:
        if op == '+':
            return a + b
        if op == '-':
            return a - b
        if op == '*':
            return a * b
        if op == '/':
            if b == 0:
                raise ValueError("Division by zero")
            return a / b
        return 0

    def evaluate_expression(tokens):
        values = []
        ops = []

        i = 0
        while i < len(tokens):
            if tokens[i] == ' ':
                i += 1
                continue

            if tokens[i].isdigit() or tokens[i] == '.':
                val = 0
                while (i < len(tokens) and (tokens[i].isdigit() or tokens[i] == '.')):
                    if tokens[i] == '.':
                        i += 1
                        decimal_place = 1
                        while (i < len(tokens) and tokens[i].isdigit()):
                            val += int(tokens[i]) / (10 ** decimal_place)
                            decimal_place += 1
                            i += 1
                        break
                    val = (val * 10) + int(tokens[i])
                    i += 1
                values.append(val)

            elif tokens[i] == '(':
                ops.append(tokens[i])
                i += 1

            elif tokens[i] == ')':
                while ops and ops[-1] != '(':
                    val2 = values.pop()
                    val1 = values.pop()
                    op = ops.pop()
                    values.append(apply_op(val1, val2, op))
                ops.pop()  # Pop '('
                i += 1

            else:
                while (ops and precedence(ops[-1]) >= precedence(tokens[i])):
                    val2 = values.pop()
                    val1 = values.pop()
                    op = ops.pop()
                    values.append(apply_op(val1, val2, op))
                ops.append(tokens[i])
                i += 1

        while ops:
            val2 = values.pop()
            val1 = values.pop()
            op = ops.pop()
            values.append(apply_op(val1, val2, op))

        return values[-1]

    return evaluate_expression(expr.replace('(', ' ( ').replace(')', ' ) ').split())

class TokenType:
    NUMBER = 'NUMBER'
    PLUS = 'PLUS'
    MINUS = 'MINUS'
    MULT = 'MULT'
    DIV = 'DIV'
    LPAREN = 'LPAREN'
    RPAREN = 'RPAREN'
    EOF = 'EOF'


class Token:
    def __init__(self, token_type, value=None):
        self.token_type = token_type
        self.value = value

    def __repr__(self):
        return f"Token({self.token_type}, {self.value})"


class Lexer:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.current_char = self.text[self.pos]

    def error(self):
        raise Exception('Invalid character')

    def advance(self):
        self.pos += 1
        if self.pos < len(self.text):
            self.current_char = self.text[self.pos]
        else:
            self.current_char = None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self):
        result = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            result += self.current_char
            self.advance()
        return Token(TokenType.NUMBER, float(result))

    def get_next_token(self):
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue
            if self.current_char.isdigit() or self.current_char == '.':
                return self.number()
            if self.current_char == '+':
                self.advance()
                return Token(TokenType.PLUS)
            if self.current_char == '-':
                self.advance()
                return Token(TokenType.MINUS)
            if self.current_char == '*':
                self.advance()
                return Token(TokenType.MULT)
            if self.current_char == '/':
                self.advance()
                return Token(TokenType.DIV)
            if self.current_char == '(':
                self.advance()
                return Token(TokenType.LPAREN)
            if self.current_char == ')':
                self.advance()
                return Token(TokenType.RPAREN)
            self.error()
        return Token(TokenType.EOF)


class Interpreter:
    def __init__(self, lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()

    def error(self):
        raise Exception('Invalid expression')

    def eat(self, token_type):
        if self.current_token.token_type == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            self.error()

    def factor(self):
        token = self.current_token
        if token.token_type == TokenType.NUMBER:
            self.eat(TokenType.NUMBER)
            return token.value
        elif token.token_type == TokenType.LPAREN:
            self.eat(TokenType.LPAREN)
            result = self.expr()
            self.eat(TokenType.RPAREN)
            return result

    def term(self):
        result = self.factor()
        while self.current_token.token_type in (TokenType.MULT, TokenType.DIV):
            token = self.current_token
            if token.token_type == TokenType.MULT:
                self.eat(TokenType.MULT)
                result *= self.factor()
            elif token.token_type == TokenType.DIV:
                self.eat(TokenType.DIV)
                result /= self.factor()
        return result

    def expr(self):
        result = self.term()
        while self.current_token.token_type in (TokenType.PLUS, TokenType.MINUS):
            token = self.current_token
            if token.token_type == TokenType.PLUS:
                self.eat(TokenType.PLUS)
                result += self.term()
            elif token.token_type == TokenType.MINUS:
                self.eat(TokenType.MINUS)
                result -= self.term()
        return result


def evaluate(expr: str) -> float:
    """
    Evaluates the given arithmetic expression using a lexer and parser.
    This approach follows the recursive descent parsing technique to handle
    the operator precedence and parentheses.
    """
    lexer = Lexer(expr)
    interpreter = Interpreter(lexer)
    return interpreter.expr()
